INSERT INTO quality_profiles (name, description, upgrades_allowed, minimum_custom_format_score, upgrade_until_score, upgrade_score_increment) VALUES ('TRaSH Remux + WEB 2160p', 'TRaSH Guides profile Remux + WEB 2160p (fd161a61e3ab826d3a22d53f935696dd), https://github.com/TRaSH-Guides/Guides @ 6986f2a94441c05cd880c5840fc0d5857c908e1d. Upgrade until Remux-2160p. WEB 2160p (WEBRip-2160p, WEBDL-2160p) is allowed below it. Other qualities are disabled. Minimum custom format score 0, upgrade until score 10000, upgrade increment 1. Custom format scores are the TRaSH default scores, including TrueHD Atmos, DTS-X, and DD+ Atmos. The Movies 2160p audio layer is not applied.', 1, 0, 10000, 1);
